import numpy as np, torch, model, inspect
print(inspect.signature(model.load))
net=model.load()
try:
    ref=model.load('v6'); print('loaded v6')
except Exception as e:
    ref=None; print('no ref',e)
cs=np.linspace(0.02,0.98,13)
torch.manual_seed(0)
for name,n in [('cand',net),('ref',ref)]:
    if n is None: continue
    for i in [3,6]:
        row=[]
        for c in cs:
            torch.manual_seed(1); xi=torch.randn(1024,2); a=model.decode(n,xi,torch.full((1024,),float(c)))
            a=a[0] if isinstance(a,tuple) else a
            row.append(np.asarray(model.in_basin(i,a)).mean())
        print(name,i,np.round(row,3))
if ref is not None:
    for c in [0.1,0.5,0.9]:
        torch.manual_seed(2); xi=torch.randn(2048,2)
        a=np.asarray(model.decode(net,xi,torch.full((2048,),c))[0]); b=np.asarray(model.decode(ref,xi,torch.full((2048,),c))[0])
        d=np.linalg.norm(a-b,axis=1); print(c,'median move',np.median(d),'frac>0.3',(d>0.3).mean())
